/**
 * app.js — Hardened Express application
 *
 * Security fixes applied (OWASP Top 10):
 *  - [A02] Sensitive data stripped from API responses; PII never exposed unauthenticated
 *  - [A03] Input validation on all user-supplied params via express-validator
 *  - [A04] Rate limiting on all routes (express-rate-limit)
 *  - [A05] Security headers via helmet; X-Powered-By disabled; CORS locked down
 *  - [A07] JWT authentication middleware guards all non-public endpoints
 *  - General: secrets from env vars only; body parser size-limited; safe defaults
 *
 * Required packages (add to package.json):
 *   npm install helmet express-rate-limit cors jsonwebtoken express-validator
 */

'use strict';

const express   = require('express');
const helmet    = require('helmet');        // Security headers
const rateLimit = require('express-rate-limit');
const cors      = require('cors');
const jwt       = require('jsonwebtoken');
const { param, validationResult } = require('express-validator');

// ---------------------------------------------------------------------------
// Environment / configuration
// ---------------------------------------------------------------------------
const PORT       = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET;

// Fail fast — never start with a missing secret in production
if (!JWT_SECRET) {
  throw new Error('FATAL: JWT_SECRET environment variable is not set.');
}

// ---------------------------------------------------------------------------
// In-memory data store (replace with a real DB + parameterised queries)
// Emails are intentionally omitted from GET /users responses (see A02 fix).
// ---------------------------------------------------------------------------
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// App initialisation
// ---------------------------------------------------------------------------
const app = express();

// A05 — Hide framework fingerprint
app.disable('x-powered-by');

// A05 — Enforce strict security headers (CSP, HSTS, X-Frame-Options, etc.)
app.use(helmet());

// A05 — Lock CORS to a known origin; widen only if truly required
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://your-frontend.example.com',
  methods: ['GET'],
  allowedHeaders: ['Authorization', 'Content-Type'],
}));

// A03 — Limit body size to prevent payload-flooding / DoS
app.use(express.json({ limit: '10kb' }));

// A04 — Global rate limit: 100 requests per IP per 15 minutes
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests — please try again later.' },
});
app.use(globalLimiter);

// ---------------------------------------------------------------------------
// Authentication middleware (A07)
// ---------------------------------------------------------------------------
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Expect: Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Authentication required.' });
  }

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    // Do not leak whether the token was expired, malformed, etc.
    return res.status(403).json({ error: 'Invalid or expired token.' });
  }
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Public — health check (no sensitive data)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// A07 + A02 — Authenticated; returns only non-sensitive fields
app.get('/users', requireAuth, (req, res) => {
  const safeUsers = USERS.map(({ id, name }) => ({ id, name }));
  res.json(safeUsers);
});

// A03 + A07 + A02 — Validated param; no PII in response
app.get(
  '/users/:id',
  requireAuth,
  param('id')
    .isInt({ min: 1 })
    .withMessage('id must be a positive integer')
    .toInt(),
  (req, res) => {
    // Return validation errors before touching any data
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const user = USERS.find(u => u.id === req.params.id);
    if (!user) {
      return res.status(404).json({ error: 'User not found.' });
    }

    // A02 — Never expose email or other PII to the caller
    const { id, name } = user;
    res.json({ id, name });
  }
);

// ---------------------------------------------------------------------------
// 404 fallback — avoids leaking route structure via default Express errors
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ---------------------------------------------------------------------------
// Global error handler — never expose stack traces to the client
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(err); // Log internally (use a structured logger in production)
  res.status(500).json({ error: 'Internal server error.' });
});

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

