### 4. 🚨 Broken Authentication — No Auth Middleware *(OWASP A07 – Identification & Authentication Failures)*

**Problem:** There is no authentication or authorisation layer anywhere. Any request to any route is served without verification.

**Fix:** Implement a `requireAuth` guard. The example below uses JWT (a common, stateless approach):

```js
const jwt = require('jsonwebtoken');
const JWT_SECRET = process.env.JWT_SECRET; // NEVER hardcode secrets

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token' });
