// Limit body size to prevent DoS via large payloads
app.use(express.json({ limit: '10kb' }));

// Example of a validated route
app.get(
  '/users/:id',
  requireAuth,
  param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
