  const safeUsers = users.map(u =>
    Object.fromEntries(SAFE_USER_FIELDS.map(f => [f, u[f]]))
  );
  res.json(safeUsers);
});
```

---

### 2. No Input Validation or Sanitization (OWASP A03)

**Problem:** The app uses `express` but never calls `express.json()` or `express.urlencoded()`. More critically, there is **no validation layer** whatsoever. Any future route that reads `req.body`, `req.query`, or `req.params` is immediately vulnerable to injection (SQL, NoSQL, command), prototype pollution, and type-confusion attacks.

```js
// ❌ CURRENT — body parser missing, no validation anywhere
const express = require('express');
const app = express();
// ← no app.use(express.json()) 
// ← no sanitisation before any data is used
```

**Fix:** Add body parsing with a strict size limit and validate every external input with a schema library:

```js
// ✅ FIXED — safe body parsing + input validation
const express = require('express');
const { body, param, validationResult } = require('express-validator'); // npm i express-validator

const app = express();

// Limit payload size to prevent DoS via large bodies
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Reusable validation error handler
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// Example: validated route for a future POST /users endpoint
app.post(
  '/users',
  requireAuth,
  body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  validate,
  (req, res) => {
    // req.body is now safe to use
  }
);
```

---

## 🟠 Medium Severity

### 3. Missing Security HTTP Headers (OWASP A05)

**Problem:** Express, by default, sends the `X-Powered-By: Express` header (fingerprinting) and omits all defensive headers (`Content-Security-Policy`, `X-Frame-Options`, `Strict-Transport-Security`, etc.), making the app easier to target.

```js
// ❌ CURRENT — no security headers configured
```

**Fix:** Add `helmet` — a single middleware that sets ~14 secure headers automatically:

```js
// ✅ FIXED
const helmet = require('helmet'); // npm i helmet
app.use(helmet());               // sets CSP, HSTS, X-Frame-Options, removes X-Powered-By, etc.
```

---

### 4. No Rate Limiting (OWASP A04, DoS)

**Problem:** All endpoints, including `/users`, accept unlimited requests. This enables brute-force attacks, credential stuffing, and trivial denial-of-service.

```js
// ❌ CURRENT — unlimited requests to all routes
```

**Fix:**

```js
// ✅ FIXED
const rateLimit = require('express-rate-limit'); // npm i express-rate-limit

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max 100 requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

app.use(limiter); // apply globally; tighten further on auth routes
```

---

### 5. Server Listens on All Interfaces (OWASP A05)

**Problem:** `app.listen(3000)` binds to `0.0.0.0` — every network interface, including public ones. In a cloud VM or container, this can unintentionally expose the port directly to the internet.

```js
// ❌ CURRENT
app.listen(3000, () => { ... });
```

**Fix:** Bind explicitly to `localhost` in development, and use an environment variable for port so production environments can override it cleanly:

```js
// ✅ FIXED
const PORT = parseInt(process.env.PORT, 10) || 3000;
const HOST = process.env.HOST || '127.0.0.1'; // localhost only; reverse-proxy handles public traffic

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

---

### 6. `/health` Endpoint Leaks Server Timing (OWASP A05)

**Problem:** Returning `new Date().toISOString()` in a public health endpoint leaks the server's exact clock, which aids timing attacks and reveals timezone/infrastructure details.

```js
// ❌ CURRENT
res.json({ status: 'ok', timestamp: new Date().toISOString() });
```

**Fix:** Return only the status (and optionally a version string from `package.json`):

```js
// ✅ FIXED
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

---

## 🟡 Low Severity / Best Practices

### 7. No CORS Policy (OWASP A05)

Without an explicit CORS policy, either all cross-origin requests are blocked (breaking legitimate clients) or a careless blanket `*` will be added later under pressure. Define it explicitly from the start:

```js
const cors = require('cors'); // npm i cors
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

### 8. No Centralised Error Handler (OWASP A09)

Unhandled errors in Express will emit stack traces to the client in development and crash the process in production. Add a catch-all:

```js
// Must be registered AFTER all routes
app.use((err, req, res, next) => {
  console.error(err); // log internally (use a real logger in prod)
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
  });
});
```

