/**
 * app.js — Security-hardened Express server
 * Addresses: OWASP A01, A02, A03, A05, A07
 *
 * Required packages:
 *   npm install helmet express-rate-limit cors jsonwebtoken express-validator
 */

'use strict';

const express    = require('express');
const helmet     = require('helmet');           // FIX #1: Security headers
const rateLimit  = require('express-rate-limit'); // FIX #2: Rate limiting
const cors       = require('cors');             // FIX #5: CORS policy
const jwt        = require('jsonwebtoken');
const { param, validationResult } = require('express-validator'); // FIX #4: Input validation

const app = express();

// ─── GLOBAL MIDDLEWARE ────────────────────────────────────────────────────────

// FIX #1 — Remove X-Powered-By and add 11 protective HTTP headers
app.use(helmet());

// FIX #5 — Restrict cross-origin requests to an explicit allowlist
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://yourdomain.com',
  methods: ['GET'],
  allowedHeaders: ['Authorization', 'Content-Type'],
}));

// FIX #2 — Rate limiting: max 100 requests per IP per 15-minute window
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// Parse JSON bodies (required for POST/PUT routes added in future)
app.use(express.json());

// ─── AUTH MIDDLEWARE ─────────────────────────────────────────────────────────

/**
 * FIX #3 — Authenticate requests using a signed JWT.
 * Expects: Authorization: Bearer <token>
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // "Bearer <token>"

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: missing token' });
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    console.error('FATAL: JWT_SECRET environment variable is not set');
    return res.status(500).json({ error: 'Internal server error' });
  }

  jwt.verify(token, secret, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Forbidden: invalid or expired token' });
    }
    req.user = user; // Attach verified user payload to request
    next();
  });
};

// ─── ROUTES ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Public endpoint — no auth required. Safe: returns no sensitive data.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * FIX #3 — Protected: requires a valid JWT.
 * In production, replace the inline array with a parameterized DB query.
 */
app.get('/users', authenticateToken, (req, res) => {
  // NOTE: In a real app, fetch from DB with a parameterized query, e.g.:
  //   db.query('SELECT id, name, email FROM users WHERE active = $1', [true])
  //   Never interpolate user input into a query string.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  res.json(users);
});

/**
 * GET /users/:id
 * FIX #4 — Input validation: :id must be a positive integer.
 * Prevents injection and unexpected crashes from malformed input.
 */
app.get(
  '/users/:id',
  authenticateToken,
  param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id, 10); // Safe: validated as integer above

    // NOTE: Use a parameterized query here, e.g.:
    //   db.query('SELECT id, name, email FROM users WHERE id = $1', [userId])
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    const user = users.find(u => u.id === userId);
    if (!user) return res.status(404).json({ error: 'User not found' });

    res.json(user);
  }
);

// ─── GLOBAL ERROR HANDLER ────────────────────────────────────────────────────

/**
 * Catch-all error handler: prevents stack traces from leaking in responses.
 * Addresses OWASP A05 (Security Misconfiguration).
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(err.stack); // Log internally, never expose to client
  res.status(500).json({ error: 'Internal server error' });
});

// ─── START ───────────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

