'use strict';

/**
 * app.js — Hardened Express application
 * Addresses: Auth, Sensitive Data Exposure, Security Headers,
 *            Input Validation, Rate Limiting, Info Leakage
 */

const express = require('express');
const helmet  = require('helmet');           // OWASP A05: Security headers
const rateLimit = require('express-rate-limit'); // OWASP A07/A04: Rate limiting
const jwt     = require('jsonwebtoken');      // OWASP A07: Authentication
const { query, validationResult } = require('express-validator'); // OWASP A03: Input validation

const app = express();

// ─────────────────────────────────────────────
// 1. GLOBAL MIDDLEWARE
// ─────────────────────────────────────────────

// Sets X-Frame-Options, Content-Security-Policy, X-Content-Type-Options,
// Strict-Transport-Security, removes X-Powered-By, and more.
app.use(helmet());

app.use(express.json({ limit: '10kb' })); // prevent oversized payload attacks

// Global rate limiter — 100 requests per 15 min per IP
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,   // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,     // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
}));

// ─────────────────────────────────────────────
// 2. AUTHENTICATION MIDDLEWARE
// ─────────────────────────────────────────────

/**
 * requireAuth — validates a signed JWT Bearer token.
 * JWT_SECRET must be set in the environment (never hardcoded).
 */
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed authorization header.' });
  }
  const token = authHeader.slice(7);
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    // Do not leak whether the token was expired vs. invalid
    return res.status(401).json({ error: 'Invalid or expired token.' });
  }
}

// ─────────────────────────────────────────────
// 3. ROUTES
// ─────────────────────────────────────────────

/**
 * GET /health
 * Public — returns only operational status, no server metadata.
 */
app.get('/health', (req, res) => {
  // FIX (Finding 6): Removed timestamp to prevent information leakage.
  res.json({ status: 'ok' });
});

/**
 * GET /users
 * Protected — requires a valid JWT.
 * FIX (Finding 1): Auth-gated; only non-sensitive fields returned.
 * FIX (Finding 4): Query param `id` is validated before use.
 */
app.get(
  '/users',
  requireAuth, // FIX (Finding 2): enforce authentication
  [
    // Optional ?id= filter: must be a positive integer if provided
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('id must be a positive integer')
      .toInt(),
  ],
  (req, res) => {
    // Return 400 if any validation rule failed
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In production this would be a parameterised DB query, never string interpolation.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    // FIX (Finding 1): Strip PII — only expose id and name to authenticated callers.
    // Expose email only to admins (role check example).
    const sanitize = (u) =>
      req.user?.role === 'admin'
        ? { id: u.id, name: u.name, email: u.email }
        : { id: u.id, name: u.name };

    const { id } = req.query;
    const result = id
      ? allUsers.filter((u) => u.id === id).map(sanitize)
      : allUsers.map(sanitize);

    res.json(result);
  }
);

// ─────────────────────────────────────────────
// 4. GLOBAL ERROR HANDLER
// ─────────────────────────────────────────────

// Catches any unhandled errors and returns a generic message.
// Prevents stack traces / internal details from leaking to clients.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  console.error(err); // log internally
  res.status(500).json({ error: 'An unexpected error occurred.' });
});

// ─────────────────────────────────────────────
// 5. SERVER BOOTSTRAP
// ─────────────────────────────────────────────

// Only start listening when run directly (not when imported by tests)
if (require.main === module) {
  if (!process.env.JWT_SECRET) {
    console.error('FATAL: JWT_SECRET environment variable is not set. Refusing to start.');
    process.exit(1);
  }
  const PORT = parseInt(process.env.PORT, 10) || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

