app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── 3. CORS POLICY ─────────────────────────────────────────────────────────
// Explicit allowlist — never use '*' for authenticated APIs
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? ['https://yourdomain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400,
};
app.use(cors(corsOptions));

// ─── 4. RATE LIMITING ───────────────────────────────────────────────────────
// Mitigates brute-force and DoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15-minute window
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(apiLimiter);

// ─── 5. AUTHENTICATION MIDDLEWARE ───────────────────────────────────────────
// Verifies a signed JWT from the Authorization: Bearer <token> header.
// JWT_SECRET must be set in the environment — never hardcode it.
function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
