// ─── 6. AUTHORIZATION MIDDLEWARE ────────────────────────────────────────────
// Role-based access control guard (usage: authorize('admin', 'superuser'))
function authorize(...roles) {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// ─── ROUTES ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Public — returns minimal liveness signal only.
 */
app.get('/health', (req, res) => {
  // ✅ No timestamp or internal details exposed
  res.json({ status: 'ok' });
});

/**
 * GET /users
 * Private — requires a valid JWT with the 'admin' role.
 * Returns a paginated, field-filtered list (no PII).
 */
app.get('/users', authenticate, authorize('admin'), (req, res) => {
  // ✅ Validate and sanitise pagination query parameters
  const pageNum  = Math.max(1, parseInt(req.query.page,  10) || 1);
  const limitNum = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 20));

  // In a real application this data comes from a database.
  // Passwords, tokens, and other secrets must never appear in this array.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   role: 'user' },
  ];

