  const safeUsers = users
    .slice((pageNum - 1) * limitNum, pageNum * limitNum)
    .map(({ id, name }) => ({ id, name })); // email/role intentionally omitted

  res.json({ data: safeUsers, page: pageNum, limit: limitNum });
});

// ─── 7. CENTRALISED ERROR HANDLER ───────────────────────────────────────────
// Must be the last middleware registered.
// Logs full details internally; returns a safe message to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Replace with a structured logger (e.g. winston / pino) in production
  console.error({
    message:  err.message,
    stack:    err.stack,
    method:   req.method,
    url:      req.url,
    ip:       req.ip,
  });

  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    // Never leak stack traces or internal messages for 5xx errors
    error: statusCode < 500 ? err.message : 'An internal error occurred',
  });
});

// ─── SERVER ──────────────────────────────────────────────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

