/**
 * app.js — hardened Express application
 *
 * Security fixes applied:
 *  - Helmet for secure HTTP headers (OWASP A05)
 *  - express-rate-limit against brute-force / DoS (OWASP A04)
 *  - Authentication middleware on protected routes (OWASP A07)
 *  - Body-parser with payload size cap (OWASP A03)
 *  - express-validator for input validation (OWASP A03)
 *  - PII-aware field filtering on /users (OWASP A02)
 *  - Safe global error handler — no stack-trace leakage (OWASP A09)
 */

'use strict';

const express = require('express');
const helmet = require('helmet');                         // secure headers
const rateLimit = require('express-rate-limit');          // rate limiting
const { query, validationResult } = require('express-validator'); // input validation

const app = express();

// ─── 1. Security Headers ─────────────────────────────────────────────────────
// Removes X-Powered-By, adds CSP, HSTS, X-Frame-Options, etc.
app.use(helmet());

// ─── 2. Body Parsing with Size Limit ─────────────────────────────────────────
// Prevents memory exhaustion via oversized payloads.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 3. Global Rate Limiting ──────────────────────────────────────────────────
// 100 requests per 15-minute window per IP across all routes.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,   // Return RateLimit-* headers per RFC 6585
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(globalLimiter);

// ─── 4. Authentication Middleware ─────────────────────────────────────────────
// Replace the token-lookup logic with your real auth system
// (e.g. JWT verification against a public key, session lookup, etc.).
// Credentials must come from environment variables — NEVER hardcode them.
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'] ?? '';
  if (!authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header.' });
  }

  const token = authHeader.slice(7); // strip "Bearer "

  // ✅ TODO: replace this stub with real JWT / session verification.
  // Example using jsonwebtoken:
  //   const jwt = require('jsonwebtoken');
  //   try {
  //     req.user = jwt.verify(token, process.env.JWT_PUBLIC_KEY);
  //     return next();
  //   } catch {
  //     return res.status(401).json({ error: 'Invalid or expired token.' });
  //   }

  if (!token || token.length < 32) {
    return res.status(401).json({ error: 'Invalid token.' });
  }

  // Attach a minimal user context for downstream handlers.
  req.user = { id: token }; // replace with decoded JWT payload
  return next();
}

// ─── 5. Public Routes ────────────────────────────────────────────────────────

// Health check — intentionally unauthenticated; returns no sensitive data.
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── 6. Protected Routes ─────────────────────────────────────────────────────

// Input validation rules for /users
const usersQueryValidation = [
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 }).withMessage('page must be an integer between 1 and 1000')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).withMessage('limit must be an integer between 1 and 100')
    .toInt(),
];

app.get(
  '/users',
  requireAuth,              // ✅ authentication required
  usersQueryValidation,     // ✅ validate & sanitize query params
  (req, res) => {
    // Return validation errors before touching any data.
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // ─── IMPORTANT: when connecting a real database, ALWAYS use
    // parameterized queries / an ORM — never string concatenation.
    // Example (node-postgres):
    //   const { rows } = await pool.query(
    //     'SELECT id, name FROM users LIMIT $1 OFFSET $2',
    //     [limit, (page - 1) * limit]
    //   );

    // ✅ Return only non-sensitive fields.
    // Email is PII — only return it if the caller owns the record
    // or has an explicit admin role.
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    return res.json(users);
  }
);

// ─── 7. Global Error Handler ─────────────────────────────────────────────────
// Must have exactly 4 parameters so Express treats it as an error handler.
// Never send stack traces or internal details to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log the full error server-side (use a structured logger in production).
  console.error('[ERROR]', err);

  const statusCode = typeof err.status === 'number' ? err.status : 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An internal server error occurred.' : err.message,
  });
});

// ─── 8. Start Server ──────────────────────────────────────────────────────────
if (require.main === module) {
  const PORT = Number(process.env.PORT) || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

