const REQUIRED_ENV = ['JWT_SECRET', 'PORT'];
REQUIRED_ENV.forEach((key) => {
  if (!process.env[key]) {
    console.error(`FATAL: missing required environment variable "${key}"`);
    process.exit(1);              // ← fail fast rather than run insecurely
  }
});

const PORT = parseInt(process.env.PORT, 10);

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### Finding 6 — No HTTPS / Transport Security *(OWASP A02)*
**Severity: 🔴 High**

**Problem:** The app listens on plain HTTP. Any credentials or PII in transit are **unencrypted and interceptable**.

**Fix:** Enforce HTTPS — either terminate TLS at a reverse proxy (recommended for production) or directly in Node.

```js
// ✅ OPTION A — redirect HTTP → HTTPS (works behind nginx / ALB)
app.use((req, res, next) => {
  if (req.headers['x-forwarded-proto'] !== 'https' && process.env.NODE_ENV === 'production') {
    return res.redirect(301, `https://${req.hostname}${req.url}`);
  }
  next();
});

// ✅ OPTION B — native HTTPS server (for standalone Node deployments)
const https = require('https');
const fs    = require('fs');
https.createServer(
  {
    key:  fs.readFileSync(process.env.TLS_KEY_PATH),
    cert: fs.readFileSync(process.env.TLS_CERT_PATH),
  },
  app
).listen(443);
```

