input.content:
/**
 * app.js — Security-hardened Express application
 *
 * Fixes applied:
 *  1. helmet()          → Security headers (OWASP A05)
 *  2. express-rate-limit → Rate limiting / DoS protection (OWASP A04)
 *  3. authenticateToken  → JWT-based auth on protected routes (OWASP A07)
 *  4. validateQuery      → Input validation middleware (OWASP A03)
 *  5. globalErrorHandler → Safe error responses, no stack-trace leakage (OWASP A09)
 *  6. Scoped /users      → No unauthenticated PII exposure (OWASP A02)
 *
 * Required packages:
 *   npm install helmet express-rate-limit jsonwebtoken zod
 */

'use strict';

const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt     = require('jsonwebtoken');
const { z }   = require('zod');

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, CSP, HSTS, and removes
// the X-Powered-By fingerprint header automatically.
app.use(helmet());

// ─── 2. BODY PARSING (scoped + size-limited) ────────────────────────────────
// Limit body size to prevent payload-based DoS attacks.
app.use(express.json({ limit: '10kb' }));

// ─── 3. RATE LIMITING ────────────────────────────────────────────────────────
// Global limiter: 100 requests per 15 minutes per IP.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,   // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,     // Disable deprecated X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(globalLimiter);

// Stricter limiter for auth-sensitive endpoints.
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Too many auth attempts. Please try again later.' },
});

// ─── 4. JWT AUTHENTICATION MIDDLEWARE ────────────────────────────────────────
// FIX: All non-public routes are protected by verifying a signed JWT.
// The secret MUST come from an environment variable — never hardcoded.
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  console.error('FATAL: JWT_SECRET environment variable is not set. Exiting.');
  process.exit(1);
}

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Authentication token required.' });
  }

  jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }, (err, user) => {
    if (err) {
      // Distinguish between expired and invalid tokens for better UX
      const message = err.name === 'TokenExpiredError'
        ? 'Token has expired.'
        : 'Invalid token.';
      return res.status(403).json({ error: message });
    }
    req.user = user; // Attach verified payload to request
    next();
  });
}

// ─── 5. INPUT VALIDATION HELPER ──────────────────────────────────────────────
// FIX: Wrap a Zod schema into reusable validation middleware.
// Use on any route that accepts query params or a request body.
function validateQuery(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.query);
    if (!result.success) {
      return res.status(400).json({
        error: 'Invalid query parameters.',
        details: result.error.flatten().fieldErrors,
      });
    }
    req.validatedQuery = result.data; // Use sanitized data downstream
    next();
  };
}

// ─── ROUTES ──────────────────────────────────────────────────────────────────

// PUBLIC: Health check — no auth needed, but still rate-limited by global limiter.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// PROTECTED: Users list — requires a valid JWT.
// FIX: Added authenticateToken so unauthenticated callers get a 401.
// FIX: Added query validation to safely handle optional filtering params.
const usersQuerySchema = z.object({
  limit: z.coerce.number().int().min(1).max(100).optional().default(20),
  offset: z.coerce.number().int().min(0).optional().default(0),
});

app.get(
  '/users',
  authLimiter,                        // Stricter rate limit on data endpoints
  authenticateToken,                  // Must be authenticated
  validateQuery(usersQuerySchema),    // Query params must be valid
  (req, res) => {
    const { limit, offset } = req.validatedQuery;

    // In a real app: query the DB using parameterized statements only,
    // e.g., db.query('SELECT id, name, email FROM users LIMIT $1 OFFSET $2', [limit, offset])
    // Never interpolate req.query values directly into a query string.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

