const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt     = require('jsonwebtoken');
const { z }   = require('zod');

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, CSP, HSTS, and removes
// the X-Powered-By fingerprint header automatically.
app.use(helmet());

