/**
 * app.js — Hardened Express application
 *
 * Security fixes applied:
 *  - JWT authentication on protected routes          (OWASP A07)
 *  - Role-based PII/data exposure control            (OWASP A02)
 *  - Input validation via express-validator          (OWASP A03)
 *  - Rate limiting via express-rate-limit            (OWASP A04)
 *  - Security headers via helmet                     (OWASP A05)
 *  - Explicit CORS allowlist via cors                (OWASP A05)
 *  - Request body size cap                           (OWASP A04)
 *  - X-Powered-By header removed                     (OWASP A05)
 *
 * Required packages:
 *   npm install express helmet cors express-rate-limit jsonwebtoken express-validator dotenv
 */

'use strict';

require('dotenv').config(); // load JWT_SECRET and ALLOWED_ORIGINS from .env

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const jwt       = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');

const app = express();

// ─── 1. REMOVE SERVER FINGERPRINT ────────────────────────────────────────────
app.disable('x-powered-by'); // belt-and-suspenders; helmet also does this

// ─── 2. SECURITY HEADERS (XSS, clickjacking, MIME sniffing, HSTS…) ───────────
app.use(helmet());

// ─── 3. CORS — explicit origin allowlist only ────────────────────────────────
const allowedOrigins = process.env.ALLOWED_ORIGINS
  ? process.env.ALLOWED_ORIGINS.split(',').map(o => o.trim())
  : [];

app.use(cors({
  origin: (origin, callback) => {
    // Allow server-to-server calls (no Origin header) only in non-production
    if (!origin && process.env.NODE_ENV !== 'production') return callback(null, true);
    if (allowedOrigins.includes(origin)) return callback(null, true);
    callback(new Error(`CORS: origin '${origin}' not allowed`));
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// ─── 4. BODY PARSING — capped at 10 kb to prevent payload-flood DoS ──────────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 5. RATE LIMITING — 100 requests / 15 min per IP ─────────────────────────
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests — please try again later.' },
});
app.use(limiter);

// ─── 6. JWT AUTHENTICATION MIDDLEWARE ────────────────────────────────────────
/**
 * Verifies a Bearer token from the Authorization header.
 * On success, attaches the decoded payload to req.user.
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // "Bearer <token>"

  if (!token) {
    return res.status(401).json({ error: 'Access token required.' });
  }

  if (!process.env.JWT_SECRET) {
    console.error('FATAL: JWT_SECRET environment variable is not set.');
    return res.status(500).json({ error: 'Server misconfiguration.' });
  }

  jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] }, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    req.user = user; // { id, role, … }
    next();
  });
}

// ─── 7. VALIDATION ERROR HANDLER ─────────────────────────────────────────────
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// ─── ROUTES ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Public endpoint — no auth required, but still rate-limited and header-protected.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Protected: requires a valid JWT.
 * - Admins receive full records including email (PII).
 * - All other roles receive id + name only.
 */
app.get('/users', authenticateToken, (req, res) => {
  // In production this data comes from a parameterised DB query, never string-interpolation.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const isAdmin = req.user?.role === 'admin';

  const sanitized = users.map(({ id, name, email }) => ({
    id,
    name,
    // Only expose PII to authorised roles
    ...(isAdmin && { email }),
  }));

  res.json(sanitized);
});

/**
 * POST /users
 * Protected: requires a valid JWT with admin role.
 * Demonstrates input validation to prevent injection and bad data.
 */
app.post(
  '/users',
  authenticateToken,

  // Authorization: admin only
  (req, res, next) => {
    if (req.user?.role !== 'admin') {
      return res.status(403).json({ error: 'Insufficient permissions.' });
    }
    next();
  },

  // Input validation
  body('name')
    .isString()
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape()
    .withMessage('name must be a non-empty string up to 100 characters.'),
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('A valid email address is required.'),

  handleValidationErrors,

  (req, res) => {
