```

**Fix — omit or mask sensitive fields based on the caller's role:**
```js
// ✅ AFTER — only return what the caller is authorized to see
app.get('/users', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Strip email unless the requester is an admin
  const sanitized = users.map(({ id, name, email }) => ({
    id,
    name,
    ...(req.user.role === 'admin' && { email }),
