/**
 * app.js — Security-hardened Express application
 *
 * Fixes applied (mapped to OWASP Top 10):
 *  A01 – Broken Access Control    : requireAuth middleware on all sensitive routes
 *  A02 – Cryptographic Failures   : HTTPS redirect enforced; sensitive fields masked
 *  A03 – Injection                : express-validator input sanitization layer added
 *  A04 – Insecure Design          : rate limiting on all routes via express-rate-limit
 *  A05 – Security Misconfiguration: Helmet sets secure HTTP headers; X-Powered-By removed
 *  A07 – Auth Failures            : Bearer token validation middleware (JWT-ready stub)
 *  A09 – Logging & Monitoring     : Morgan request logger + structured error handler added
 */

'use strict';

const express = require('express');
const helmet  = require('helmet');          // npm install helmet
const morgan  = require('morgan');          // npm install morgan
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit
const { query, validationResult } = require('express-validator'); // npm install express-validator

const app = express();

// ─── 1. SECURITY HEADERS (OWASP A05) ────────────────────────────────────────
// Helmet sets Content-Security-Policy, X-Frame-Options, X-Content-Type-Options,
// Strict-Transport-Security, and a dozen more protective headers automatically.
app.use(helmet());

// Remove the "X-Powered-By: Express" fingerprinting header.
app.disable('x-powered-by');

// ─── 2. HTTPS ENFORCEMENT (OWASP A02) ───────────────────────────────────────
// In production, redirect any plain HTTP request to HTTPS immediately.
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && req.headers['x-forwarded-proto'] !== 'https') {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
});

// ─── 3. REQUEST LOGGING (OWASP A09) ─────────────────────────────────────────
// Use 'combined' format in production for full audit trails; 'dev' locally.
const logFormat = process.env.NODE_ENV === 'production' ? 'combined' : 'dev';
app.use(morgan(logFormat));

// ─── 4. BODY PARSING ─────────────────────────────────────────────────────────
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent payload attacks

// ─── 5. RATE LIMITING (OWASP A04) ────────────────────────────────────────────
// Apply a global rate limit: max 100 requests per 15-minute window per IP.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return RateLimit-* headers (RFC 6585)
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(globalLimiter);

// Apply a stricter limit on sensitive/data endpoints.
const sensitiveEndpointLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Too many requests to this endpoint. Please try again later.' },
});

// ─── 6. AUTHENTICATION MIDDLEWARE (OWASP A07) ────────────────────────────────
// Validates a Bearer token on every protected route.
// Replace the stub check with real JWT verification (e.g., jsonwebtoken.verify).
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header.' });
  }

  const token = authHeader.slice(7); // Strip "Bearer " prefix

  // ── STUB: replace this block with real JWT verification ──────────────────
  // Example using jsonwebtoken:
  //   const jwt = require('jsonwebtoken');
  //   try {
  //     req.user = jwt.verify(token, process.env.JWT_SECRET);
  //     return next();
  //   } catch (err) {
  //     return res.status(403).json({ error: 'Invalid or expired token.' });
  //   }
  // ────────────────────────────────────────────────────────────────────────
  if (token !== process.env.API_SECRET_TOKEN) {
    return res.status(403).json({ error: 'Invalid or expired token.' });
  }

  next();
}

// ─── 7. INPUT VALIDATION HELPER (OWASP A03) ──────────────────────────────────
// Centralises validation-result checking; call after express-validator chains.
function validateInput(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(422).json({ errors: errors.array() });
  }
  next();
}

// ─── ROUTES ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Public endpoint — no auth required, but still rate-limited via global limiter.
 * Does NOT expose internal stack details.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Protected endpoint.
 *  - Requires valid Bearer token (A07).
 *  - Rate-limited to 20 req / 15 min (A04).
 *  - Accepts optional ?page & ?limit query params, validated before use (A03).
 *  - Email addresses are masked before being returned (A02).
 */
app.get(
  '/users',
  requireAuth,                    // A07 – authentication gate
  sensitiveEndpointLimiter,       // A04 – tighter rate limit
  [
    // A03 – validate & sanitize all incoming query parameters
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('page must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('limit must be an integer between 1 and 100')
      .toInt(),
  ],
  validateInput,                  // A03 – reject invalid input early
  (req, res) => {
    // In a real application, query the database here using parameterised queries,
    // e.g.: db.query('SELECT id, name, email FROM users LIMIT $1 OFFSET $2', [limit, offset])
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    // A02 – mask sensitive PII before sending the response
    const safeUsers = users.map(maskUserPII);

    res.json(safeUsers);
  }
);

// ─── 8. SENSITIVE DATA MASKING (OWASP A02) ───────────────────────────────────
/**
 * Masks a user's email address before the object is serialised into the response.
 * "alice@example.com" → "a***@example.com"
 *
 * Extend this function to mask any other PII fields (phone, SSN, etc.).
 */
function maskUserPII(user) {
  const [localPart, domain] = (user.email || '').split('@');
  const maskedEmail = localPart
    ? `${localPart[0]}***@${domain}`
    : '[redacted]';

  return {
    id:    user.id,
    name:  user.name,
    email: maskedEmail,
    // Deliberately omit password hashes, tokens, or any other sensitive fields.
  };
}

// ─── 9. GLOBAL ERROR HANDLER (OWASP A09) ─────────────────────────────────────
// Catches any unhandled errors and returns a safe, generic message.
// The full error is logged server-side but never leaked to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${req.method} ${req.path} —`, err);
  res.status(500).json({ error: 'An internal server error occurred.' });
});

// ─── SERVER ──────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
});

module.exports = app;

