// ✅ FIX: Use HTTPS and mask sensitive fields
const https = require('https');
const fs = require('fs');

const tlsOptions = {
  key:  fs.readFileSync(process.env.TLS_KEY_PATH),
  cert: fs.readFileSync(process.env.TLS_CERT_PATH),
};

https.createServer(tlsOptions, app).listen(443);

// Strip email (PII) unless the caller has explicit permission
app.get('/users', requireAuth, (req, res) => {
  const users = getAllUsers().map(({ id, name }) => ({ id, name })); // omit email
  res.json(users);
});
```

