require('dotenv').config(); // Never hardcode secrets

const express    = require('express');
const https      = require('https');
const fs         = require('fs');
const helmet     = require('helmet');
const cors       = require('cors');
const morgan     = require('morgan');
const rateLimit  = require('express-rate-limit');
const jwt        = require('jsonwebtoken');
const winston    = require('winston');
const { z }      = require('zod');

const app = express();

// ── Logging ──────────────────────────────────────────────────────────────────
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.File({ filename: 'app.log' })],
});
app.use(morgan('combined', { stream: { write: (m) => logger.info(m.trim()) } }));

// ── Security Headers ──────────────────────────────────────────────────────────
app.use(helmet());

// ── CORS ─────────────────────────────────────────────────────────────────────
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || '').split(',');
app.use(cors({
  origin: (origin, cb) =>
    (!origin || ALLOWED_ORIGINS.includes(origin)) ? cb(null, true) : cb(new Error('CORS policy violation')),
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Authorization', 'Content-Type'],
}));

// ── Body Parsing (with size limit to prevent payload flooding) ───────────────
app.use(express.json({ limit: '10kb' }));

// ── Rate Limiting ─────────────────────────────────────────────────────────────
const globalLimit    = rateLimit({ windowMs: 15 * 60 * 1000, max: 100 });
const sensitiveLimit = rateLimit({ windowMs: 15 * 60 * 1000, max: 20  });
app.use(globalLimit);

// ── Auth Middleware ───────────────────────────────────────────────────────────
function requireAuth(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    logger.warn('Auth failure', { ip: req.ip, path: req.path });
    return res.status(403).json({ error: 'Forbidden' });
  }
}

// ── Input Validation Schemas ──────────────────────────────────────────────────
const UserQuerySchema = z.object({
  id: z.coerce.number().int().positive().optional(),
});

// ── Routes ────────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', sensitiveLimit, requireAuth, (req, res) => {
  const result = UserQuerySchema.safeParse(req.query);
  if (!result.success) {
    return res.status(400).json({ error: 'Invalid query', details: result.error.flatten() });
  }
  // Return only non-sensitive fields; scope to caller's role in a real app
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob'   },
  ];
  res.json(users);
});

// ── Global Error Handler ──────────────────────────────────────────────────────
app.use((err, req, res, _next) => {
  logger.error('Unhandled error', { message: err.message, stack: err.stack });
  res.status(500).json({ error: 'Internal server error' }); // never leak stack traces
});

// ── TLS Server ────────────────────────────────────────────────────────────────
const tlsOptions = {
  key:  fs.readFileSync(process.env.TLS_KEY_PATH),
  cert: fs.readFileSync(process.env.TLS_CERT_PATH),
};
https.createServer(tlsOptions, app).listen(443, () => {
  logger.info('Secure server running on port 443');
});

module.exports = app;
```

