'use strict';

/**
 * app.js — Hardened Express Application
 * Addresses OWASP Top 10 vulnerabilities identified in security audit.
 *
 * Required packages:
 *   npm install express helmet express-rate-limit morgan express-validator jsonwebtoken dotenv
 */

require('dotenv').config(); // Load secrets from .env — NEVER hardcode credentials

const express    = require('express');
const helmet     = require('helmet');           // A05: Security headers
const rateLimit  = require('express-rate-limit'); // A04: Rate limiting
const morgan     = require('morgan');            // A09: Request logging
const jwt        = require('jsonwebtoken');      // A07: Authentication
const { query, validationResult } = require('express-validator'); // A03: Input validation

const app = express();

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS (OWASP A05 – Security Misconfiguration)
//    helmet sets: X-Frame-Options, Content-Security-Policy, HSTS, X-XSS-Protection,
//    X-Content-Type-Options, Referrer-Policy, Permissions-Policy, etc.
// ---------------------------------------------------------------------------
app.use(helmet());
app.disable('x-powered-by'); // Hide Express fingerprint (also done by helmet)

// ---------------------------------------------------------------------------
// 2. HTTPS ENFORCEMENT (OWASP A02 – Cryptographic Failures)
//    In production, redirect plain HTTP to HTTPS.
//    HSTS header is set by helmet above.
// ---------------------------------------------------------------------------
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.headers['x-forwarded-proto'] !== 'https') {
      return res.redirect(301, `https://${req.headers.host}${req.url}`);
    }
    next();
  });
}

// ---------------------------------------------------------------------------
// 3. REQUEST LOGGING (OWASP A09 – Security Logging & Monitoring Failures)
//    'combined' format logs: IP, timestamp, method, path, status, user-agent.
//    In production, pipe this to a SIEM or log aggregator (e.g. Splunk, Datadog).
// ---------------------------------------------------------------------------
app.use(morgan('combined'));

// ---------------------------------------------------------------------------
// 4. RATE LIMITING (OWASP A04 – Insecure Design / DoS Protection)
//    Limits each IP to 100 requests per 15-minute window.
//    Tighten limits on sensitive routes (e.g., /login) as needed.
// ---------------------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,    // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,     // Disable X-RateLimit-* headers
  message: { error: 'Too many requests — please try again later.' },
});
app.use(globalLimiter);

// ---------------------------------------------------------------------------
// 5. BODY PARSING WITH SIZE LIMITS (OWASP A03 – Injection / DoS)
//    Restricts body size to prevent large-payload denial-of-service attacks.
//    'extended: false' uses the native querystring library (safer than qs).
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 6. AUTHENTICATION MIDDLEWARE (OWASP A07 – Identification & Auth Failures)
//    Verifies a signed JWT from the Authorization: Bearer <token> header.
//    JWT_SECRET must be a long, random secret stored in .env — never in source.
// ---------------------------------------------------------------------------
const authenticate = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.split(' ')[1]
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Authentication required.' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    // Distinguish expired tokens from invalid ones for better UX
    const message = err.name === 'TokenExpiredError'
      ? 'Token expired.'
      : 'Invalid token.';
    return res.status(403).json({ error: message });
  }
};

// ---------------------------------------------------------------------------
// ROUTES
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Public endpoint — no auth required.
 * Returns minimal info; avoid leaking internal version or dependency details.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Protected endpoint — requires valid JWT.
 *
 * Input validation (OWASP A03):
 *   - Optional `id` query param must be a positive integer.
 *
 * Access control (OWASP A01):
 *   - Requires authentication via `authenticate` middleware.
 *
 * Sensitive data (OWASP A02):
 *   - Emails are masked before being returned.
 *   - In a real app, apply field-level access control based on req.user.role.
 */
app.get(
  '/users',
  authenticate, // A07: enforce authentication
  [
    // A03: validate and sanitize query parameters
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('id must be a positive integer')
      .toInt(), // sanitize: coerce to integer, preventing type confusion
  ],
  (req, res) => {
    // Return validation errors before touching any data
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app: query your database using parameterized queries here.
    // NEVER interpolate req.query values directly into SQL/NoSQL queries.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    // Filter by id if provided
    const users = req.query.id
      ? allUsers.filter(u => u.id === req.query.id)
      : allUsers;

    // A02: mask sensitive PII before returning — full email only for authorized roles
    const safeUsers = users.map(({ id, name, email }) => ({
      id,
      name,
      email: maskEmail(email), // e.g. "a***@example.com"
    }));

    res.json(safeUsers);
  }
);

// ---------------------------------------------------------------------------
// 7. GLOBAL ERROR HANDLER (OWASP A05 – Security Misconfiguration)
//    Must be defined AFTER all routes (Express identifies it by 4 arguments).
//    In production: never expose stack traces or internal error details to clients.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally for debugging and monitoring
  console.error(`[ERROR] ${req.method} ${req.path} — ${err.stack}`);

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'An internal error occurred.' // A05: never leak internals in production
      : err.message,
  });
});

// ---------------------------------------------------------------------------
// HELPERS
// ---------------------------------------------------------------------------

/**
 * Masks an email address to reduce PII exposure in API responses.
 * Example: "alice@example.com" → "a***@example.com"
 */
function maskEmail(email) {
  const [local, domain] = email.split('@');
  return `${local[0]}***@${domain}`;
}

// ---------------------------------------------------------------------------
// SERVER STARTUP
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

// Validate critical environment variables before starting
if (!process.env.JWT_SECRET) {
  console.error('[FATAL] JWT_SECRET environment variable is not set. Exiting.');
  process.exit(1);
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = { app, server }; // export server for clean teardown in tests

