  query('id').optional().isInt({ min: 1 }).toInt()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });
  // ...
});
```

---

#### 🟠 4. No Rate Limiting — DoS / Brute-Force Exposure
**Risk:** An attacker can hammer any endpoint infinitely — scraping user data or brute-forcing tokens.

```js
// ❌ VULNERABLE — no rate limiting
app.get('/users', ...);
```
```js
// ✅ FIX — add express-rate-limit
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);
```

---

#### 🟡 5. No Request Logging or Security Monitoring
**Risk:** There is no visibility into who is calling the API, making incident detection and forensics impossible.

```js
// ❌ VULNERABLE — silent server
app.listen(3000, () => console.log('Server running on port 3000'));
```
```js
// ✅ FIX — add morgan for HTTP logging
const morgan = require('morgan');
app.use(morgan('combined')); // Apache-style logs with IP, method, status, user-agent
```

---

#### 🟡 6. No Global Error Handler — Stack Trace Leakage
**Risk:** Unhandled errors bubble up as default Express responses that may include stack traces, internal paths, or dependency versions.

```js
// ❌ VULNERABLE — no error handler
app.listen(3000, ...);
```
```js
// ✅ FIX — add a global error handler AFTER all routes
app.use((err, req, res, next) => {
  console.error(err.stack); // log internally
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal Server Error' // never expose internals
      : err.message
  });
});
```

---

#### 🟠 7. No HTTPS Enforcement
**Risk:** Credentials, tokens, and PII are transmitted in plaintext over HTTP.

```js
// ❌ VULNERABLE — plain HTTP only
app.listen(3000, ...);
```
```js
// ✅ FIX — redirect HTTP to HTTPS and use HSTS (via helmet)
app.use((req, res, next) => {
  if (req.headers['x-forwarded-proto'] !== 'https' && process.env.NODE_ENV === 'production') {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
