});
```

---

## Finding 7 — No CORS Policy
**OWASP A05: Security Misconfiguration | Severity: MEDIUM**

Without explicit CORS configuration, the browser's default policy applies — which may be too permissive or too restrictive depending on deployment context.

**Fix — configure `cors` explicitly:**
```js
// npm install cors
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [], // e.g. 'https://app.example.com'
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

## Finding 8 — No Centralized Error Handler
**OWASP A05: Security Misconfiguration | Severity: MEDIUM**

Without a global error handler, Express may leak stack traces and internal error details to clients in production.

**Fix — add a safe error handler as the last middleware:**
```js
// Must have 4 parameters for Express to recognize it as an error handler
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';
  console.error(err); // Log internally (use a real logger like pino/winston)

  res.status(err.status || 500).json({
    error: isDev ? err.message : 'An unexpected error occurred.', // Never leak in prod
  });
});
```

