'use strict';

const express    = require('express');
const helmet     = require('helmet');          // npm install helmet
const rateLimit  = require('express-rate-limit'); // npm install express-rate-limit
const jwt        = require('jsonwebtoken');    // npm install jsonwebtoken

const app = express();

// ── 1. Security headers ───────────────────────────────────────────────────────
app.use(helmet());
app.disable('x-powered-by');

// ── 2. Request body limits ────────────────────────────────────────────────────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ── 3. Rate limiting ──────────────────────────────────────────────────────────
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
}));

// ── 4. Authentication middleware ──────────────────────────────────────────────
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) throw new Error('FATAL: JWT_SECRET environment variable is not set.');

function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'Authentication required.' });
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token.' });
  }
}

// ── 5. Routes ─────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  // Intentionally minimal — do NOT expose version, env, or infra details
  res.json({ status: 'ok' });
});

app.get('/users', authenticate, (req, res) => {
  const page   = Math.max(1, parseInt(req.query.page)  || 1);
  const limit  = Math.min(100, parseInt(req.query.limit) || 20);
  const offset = (page - 1) * limit;

  const users = getAllUsers()             // replace with real DB call
    .slice(offset, offset + limit)
    .map(({ id, name }) => ({ id, name })); // strip PII like email

  res.json({ page, limit, data: users });
});

// ── 6. Error handling ─────────────────────────────────────────────────────────
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

app.use((err, req, res, next) => { // eslint-disable-line no-unused-vars
  console.error(err);
  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'An internal server error occurred.',
    ...(isDev && { stack: err.stack }),
  });
});

// ── 7. Server startup ─────────────────────────────────────────────────────────
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
}

module.exports = app;
```

